namespace Frociart {
 internal sealed class LoopEditorDialog:Form {
  private sealed class EdgeChoice {internal string Id,Label;public override string ToString(){return Label;}}
  internal readonly ComboBox Kind=new FlowComboBox(),Target=new FlowComboBox();
  internal readonly TextBox Variable=new TextBox(),From=new TextBox(),To=new TextBox(),Step=new TextBox(),Initialize=new TextBox(),Condition=new TextBox(),Body=new TextBox(),Preview=new TextBox();
  internal readonly Label Error=Ui.Label("",9.5f,Ui.Amber);internal readonly Button Apply;
  private readonly TableLayoutPanel fields;private readonly Label help=Ui.Label("",10,Ui.Muted);private readonly Dictionary<Control,Control> rows=new Dictionary<Control,Control>();
  private readonly FlowLoopBuilder.Spec[] drafts={FlowLoopBuilder.Spec.Default(0),FlowLoopBuilder.Spec.Default(1),FlowLoopBuilder.Spec.Default(2)};
  private int active;private bool loading;private readonly Diagram project;private readonly string functionId;internal FlowLoopBuilder.Plan Result;
  internal FlowCycle.Info Editing;internal bool SelectGroup;
  internal LoopEditorDialog(Diagram source,string id,string selectedEdge):this(source,id,selectedEdge,null){}
  internal LoopEditorDialog(Diagram source,string id,string selectedEdge,FlowCycle.Info editing){
   Editing=editing;
   project=DiagramIO.Clone(source);functionId=id;Text="Inserisci un ciclo — Frociart";StartPosition=FormStartPosition.CenterParent;ShowInTaskbar=false;AutoScaleMode=AutoScaleMode.Dpi;AutoScaleDimensions=new SizeF(96,96);Font=Ui.Font();ClientSize=new Size(680,Math.Min(790,Screen.PrimaryScreen.WorkingArea.Height-80));MinimumSize=new Size(540,500);
   var layout=new TableLayoutPanel{Dock=DockStyle.Fill,Padding=new Padding(20),ColumnCount=1,RowCount=3};layout.ColumnStyles.Add(new ColumnStyle(SizeType.Percent,100));layout.RowStyles.Add(new RowStyle(SizeType.Absolute,60));layout.RowStyles.Add(new RowStyle(SizeType.Percent,100));layout.RowStyles.Add(new RowStyle(SizeType.Absolute,104));Controls.Add(layout);
   var heading=Ui.Label("Costruisci un ciclo\nScegli la freccia: il resto del progetto viene conservato.",12,Ui.Ink,true);heading.Dock=DockStyle.Fill;layout.Controls.Add(heading,0,0);
   var scroll=new FlowScrollPanel{Dock=DockStyle.Fill,AutoScroll=true};layout.Controls.Add(scroll,0,1);fields=new TableLayoutPanel{Dock=DockStyle.Top,AutoSize=true,ColumnCount=1};fields.ColumnStyles.Add(new ColumnStyle(SizeType.Percent,100));scroll.Controls.Add(fields);
   Add("Inserisci sulla freccia",Target,38);Target.DropDownStyle=ComboBoxStyle.DropDownList;Target.AccessibleName="Freccia su cui inserire il ciclo";
   var graph=FunctionEditing.Graph(project,id);foreach(var e in graph.Edges){var a=graph.Nodes.First(n=>n.Id==e.From);var b=graph.Nodes.First(n=>n.Id==e.To);if(a.Kind==NodeKind.End||b.Kind==NodeKind.Start)continue;Target.Items.Add(new EdgeChoice{Id=e.Id,Label=(a.Kind==NodeKind.Decision?"Ramo "+a.GetBranchLabel(e.Branch)+" · ":"")+Short(a)+" → "+Short(b)});}
   if(Target.Items.Count>0){Target.SelectedIndex=0;for(int i=0;i<Target.Items.Count;i++){var edge=graph.Edges.First(e=>e.Id==((EdgeChoice)Target.Items[i]).Id);if(selectedEdge==null&&graph.Nodes.First(n=>n.Id==edge.From).Kind==NodeKind.Start||edge.Id==selectedEdge)Target.SelectedIndex=i;}}
   Add("Tipo di ciclo",Kind,38);Kind.AccessibleName="Tipo di ciclo";Kind.DropDownStyle=ComboBoxStyle.DropDownList;Kind.Items.AddRange(new object[]{"Per · un intervallo di valori","Mentre · controlla prima","Ripeti · controlla alla fine"});Kind.SelectedIndex=0;
   help.Dock=DockStyle.Fill;help.MinimumSize=new Size(0,62);fields.Controls.Add(help);
   Add("Variabile contatore",Variable,36);Add("Da (incluso)",From,36);Add("A (incluso)",To,36);Add("Passo · negativo per contare all'indietro",Step,36);Add("Prima del ciclo · facoltativo",Initialize,36);Add("Continua mentre la condizione è vera",Condition,36);
   Add("Corpo del ciclo · una istruzione per riga",Body,125);Body.Multiline=true;Body.AcceptsReturn=true;Body.ScrollBars=ScrollBars.Vertical;Body.MaxLength=32768;
   Add(editing==null?"Anteprima pseudocodice":"Riepilogo compatto",Preview,132);Preview.Multiline=true;Preview.ReadOnly=true;Preview.ScrollBars=ScrollBars.Both;Preview.WordWrap=false;Preview.Font=new Font("Consolas",10);
   foreach(var pair in new[]{Tuple.Create(Variable,"Variabile contatore"),Tuple.Create(From,"Valore iniziale"),Tuple.Create(To,"Valore finale"),Tuple.Create(Step,"Passo"),Tuple.Create(Initialize,"Istruzioni prima del ciclo"),Tuple.Create(Condition,"Condizione del ciclo"),Tuple.Create(Body,"Corpo del ciclo"),Tuple.Create(Preview,"Anteprima pseudocodice")}){pair.Item1.AccessibleName=pair.Item2;if(pair.Item1!=Body&&pair.Item1!=Preview)pair.Item1.MaxLength=8192;pair.Item1.TextChanged+=delegate{if(!loading)UpdatePreview();};}
   var footer=new TableLayoutPanel{Dock=DockStyle.Fill,ColumnCount=1,RowCount=2};footer.RowStyles.Add(new RowStyle(SizeType.Absolute,52));footer.RowStyles.Add(new RowStyle(SizeType.Percent,100));Error.Dock=DockStyle.Fill;footer.Controls.Add(Error,0,0);var actions=new FlowLayoutPanel{Dock=DockStyle.Fill,WrapContents=false};Apply=Ui.Button("Inserisci ciclo",170,Save,true);actions.Controls.Add(Apply);var cancel=Ui.Button("Annulla",110,Close);actions.Controls.Add(cancel);footer.Controls.Add(actions,0,1);layout.Controls.Add(footer,0,2);AcceptButton=Apply;CancelButton=cancel;
   if(editing!=null){Text="Modifica ciclo — Frociart";heading.Text="Un ciclo, una scheda\nIl corpo si modifica nei singoli blocchi sul foglio.";ClientSize=new Size(680,Math.Min(660,Screen.PrimaryScreen.WorkingArea.Height-80));drafts[editing.Kind]=editing.Spec;active=editing.Kind;Kind.SelectedIndex=active;Kind.Enabled=false;rows[Kind].Visible=rows[Target].Visible=rows[Body].Visible=rows[Initialize].Visible=false;Variable.ReadOnly=true;Variable.TabStop=false;Apply.Text="Salva ciclo";var select=Ui.Button("Seleziona ciclo",150,()=>{SelectGroup=true;DialogResult=DialogResult.Yes;Close();});actions.Controls.Add(select);}
   Kind.SelectedIndexChanged+=delegate{Read(drafts[active]);FlowTransitions.Change(fields);active=Kind.SelectedIndex;LoadDraft();};LoadDraft();Ui.ApplyTheme(this);FlowFormMotion.Attach(this);
  }
  private static string Short(FlowNode n){string t=(n.Text??"").Replace('\n',' ').Trim();return t.Length==0?Ui.KindName(n.Kind):t.Length>38?t.Substring(0,35)+"…":t;}
  private void Add(string label,Control control,int height){var panel=new TableLayoutPanel{Dock=DockStyle.Top,AutoSize=true,ColumnCount=1,Margin=new Padding(0,0,10,10)};panel.ColumnStyles.Add(new ColumnStyle(SizeType.Percent,100));panel.RowStyles.Add(new RowStyle(SizeType.Absolute,25));panel.RowStyles.Add(new RowStyle(SizeType.Absolute,height));var title=Ui.Label(label,9,Ui.Muted,true);title.Dock=DockStyle.Fill;panel.Controls.Add(title,0,0);control.Dock=DockStyle.Fill;panel.Controls.Add(control,0,1);fields.Controls.Add(panel);rows[control]=panel;}
  private void Read(FlowLoopBuilder.Spec s){s.Variable=Variable.Text;s.From=From.Text;s.To=To.Text;s.Step=Step.Text;s.Initialize=Initialize.Text;s.Condition=Condition.Text;s.Body=Body.Text;}
  private void LoadDraft(){loading=true;var s=drafts[active];Variable.Text=s.Variable;From.Text=s.From;To.Text=s.To;Step.Text=s.Step;Initialize.Text=s.Initialize;Condition.Text=s.Condition;Body.Text=s.Body;foreach(var c in new Control[]{Variable,From,To,Step})rows[c].Visible=active==0;rows[Initialize].Visible=active!=0&&Editing==null;rows[Condition].Visible=active!=0;help.Text=active==0?"Gli estremi sono inclusi. Inizio, limite e passo sono calcolati una volta. Il contatore viene aggiornato automaticamente.":active==1?"Controlla la condizione prima del corpo. Se è falsa, non esegue nessuna iterazione.":"Esegue il corpo almeno una volta, poi continua mentre la condizione è vera. Aggiorna nel corpo le variabili della condizione.";if(Editing!=null)help.Text="Modifica "+(active==0?"gli estremi e il passo":"la condizione")+". Il corpo, i nomi dei rami, i commenti e i punti di interruzione vengono conservati. Seleziona ciclo include "+Editing.Members.Count+" blocchi. Il contatore si rinomina nei singoli blocchi.";loading=false;UpdatePreview();}
  private void UpdatePreview(){Read(drafts[active]);if(Editing!=null){Error.Text="";Preview.Text=active==0?"PER "+Variable.Text+" DA "+From.Text+" A "+To.Text+" PASSO "+Step.Text+" FAI\r\n    Corpo esistente nel foglio\r\nFINE PER":(active==1?"MENTRE ":"RIPETI · continua mentre ")+Condition.Text+"\r\n    Corpo esistente nel foglio";Apply.Enabled=true;return;}try{Preview.Text=FlowLoopBuilder.Source(drafts[active]);Error.Text=Target.Items.Count==0?"Collega almeno due blocchi per scegliere la freccia.":"";Apply.Enabled=Target.Items.Count>0;}catch(FlowException e){Preview.Text="Completa i campi per vedere il ciclo.";Error.Text=e.Message;Apply.Enabled=false;}}
  internal void Save(){try{Read(drafts[active]);if(Editing!=null){Result=FlowCycle.Prepare(project,functionId,Editing,drafts[active]);DialogResult=DialogResult.OK;Close();return;}var target=Target.SelectedItem as EdgeChoice;if(target==null)throw new FlowException("Scegli una freccia.");Result=FlowLoopBuilder.Prepare(project,functionId,target.Id,drafts[active]);DialogResult=DialogResult.OK;Close();}catch(Exception e){if(!(e is FlowException||e is System.IO.InvalidDataException||e is ArgumentException))throw;Error.Text=e.Message;Error.AccessibleDescription=e.Message;}}
 }
 internal sealed class CycleListDialog:Form {
  internal FlowCycle.Info Selected;internal bool Overview;
  internal CycleListDialog(List<FlowCycle.Info> cycles){Text="Cicli del diagramma — Frociart";Font=Ui.Font();StartPosition=FormStartPosition.CenterParent;ShowInTaskbar=false;AutoScaleMode=AutoScaleMode.Dpi;AutoScaleDimensions=new SizeF(96,96);ClientSize=new Size(590,460);MinimumSize=new Size(440,340);var scroll=new FlowScrollPanel{Dock=DockStyle.Fill,AutoScroll=true};var body=new FlowLayoutPanel{Dock=DockStyle.Top,AutoSize=true,FlowDirection=FlowDirection.TopDown,WrapContents=false,Padding=new Padding(20)};scroll.Controls.Add(body);Controls.Add(scroll);var title=Ui.Label("Cicli del diagramma",15,Ui.Ink,true);title.Size=new Size(520,35);body.Controls.Add(title);var help=Ui.Label(cycles.Count==0?"Non ci sono cicli con un solo ingresso e una sola uscita.\nPuoi inserirne uno con Ciclo guidato, oppure modificare i singoli blocchi.":"Apri una scheda per i parametri, oppure seleziona il ciclo intero.",10,Ui.Muted);help.Size=new Size(520,70);body.Controls.Add(help);body.Controls.Add(Ui.Button("Panoramica cicli · espandi e riduci",520,()=>{Overview=true;DialogResult=DialogResult.Retry;Close();}));foreach(var cycle in cycles){var item=cycle;string text=cycle.Header;if(text.Length>120)text=text.Substring(0,117)+"…";var button=Ui.Button(text+"\n"+cycle.Members.Count+" blocchi · Parametri e selezione",520,()=>{Selected=item;DialogResult=DialogResult.OK;Close();});button.Height=78;body.Controls.Add(button);}Ui.ApplyTheme(this);FlowFormMotion.Attach(this);}
 }
 internal sealed partial class MainForm {
  private void ShowCycleManager(){if(Canvas.IsPointerGestureActive)return;CommitInspector();PauseRun();var cycles=FlowCycle.Find(Document);var selected=cycles.Where(i=>i.Members.Contains(Canvas.SelectedNodeId??"" )).OrderBy(i=>i.Members.Count).FirstOrDefault();if(selected==null){using(var list=new CycleListDialog(cycles)){var choice=list.ShowDialog(this);if(choice==DialogResult.Retry){ShowCycleOverview();return;}if(choice!=DialogResult.OK)return;selected=list.Selected;}}if(selected==null)return;EditCycleParameters(selected);}
  private void EditCycleParameters(FlowCycle.Info selected){using(var dialog=new LoopEditorDialog(Project,ActiveFunctionId,null,selected)){var outcome=dialog.ShowDialog(this);if(outcome==DialogResult.Yes){Canvas.SelectGroup(selected.Members);SetStatus("Ciclo selezionato · trascina un blocco per spostare il gruppo.");}else if(outcome==DialogResult.OK)try{ApplyLoopPlan(dialog.Result);}catch(FlowException e){ShowError("Ciclo non aggiornato",e);}}}
  private void ShowLoopEditor(){if(Canvas.IsPointerGestureActive)return;CommitInspector();PauseRun();using(var dialog=new LoopEditorDialog(Project,ActiveFunctionId,Canvas.SelectedEdgeId)){if(dialog.ShowDialog(this)==DialogResult.OK)try{ApplyLoopPlan(dialog.Result);}catch(FlowException e){ShowError("Ciclo non inserito",e);}}}
  internal void ApplyLoopPlan(FlowLoopBuilder.Plan plan){if(plan==null||plan.FunctionId!=ActiveFunctionId||plan.BaseDocument!=Convert.ToBase64String(DiagramIO.EncodeDocument(Project)))throw new FlowException("Il progetto è cambiato: riapri Inserisci ciclo per conservare il lavoro più recente.");CommitInspector();if(plan.BaseDocument!=Convert.ToBase64String(DiagramIO.EncodeDocument(Project)))throw new FlowException("Il blocco è cambiato: riapri Inserisci ciclo per conservare le modifiche.");DiagramIO.EncodeDocument(plan.Project);if(plan.Editing&&plan.BaseDocument==Convert.ToBase64String(DiagramIO.EncodeDocument(plan.Project))){SetStatus("Il ciclo è già aggiornato.");return;}
   Canvas.InsertGroupAnimated(()=>{PrepareMutation();bool wasChanging=changingDocument;changingDocument=true;try{Project=plan.Project;Canvas.Diagram=Document;Canvas.SelectNode(plan.EntryId);}finally{changingDocument=wasChanging;}MarkDirty();LoadInspector();},plan.Origin);SetStatus(plan.Editing?"Ciclo aggiornato · Ctrl+Z annulla la modifica.":"Ciclo inserito · "+plan.Added+" blocchi modificabili · Ctrl+Z annulla tutto.");
  }
 }
 public partial class FlowCanvas {
  internal void SelectGroup(IEnumerable<string> ids){if(ViewOnly)return;CancelPointerGesture(false,false);CancelConnection(false);SetSelection(ids,null);RequestFrameRepaint();}
  internal void InsertGroupAnimated(Action apply,PointF origin){CancelPointerGesture(true,true);CancelConnection(false);var before=ModelPositions();var oldSizes=_diagram.Nodes.ToDictionary(n=>n.Id,n=>DisplaySize(n));float px=_panX,py=_panY,z=_zoom;apply();_panX=px;_panY=py;_zoom=z;foreach(var node in _diagram.Nodes)if(!before.ContainsKey(node.Id))before[node.Id]=origin;EnsureScene();if(UiMotion.Enabled)foreach(var node in _diagram.Nodes){SizeF old;if(oldSizes.TryGetValue(node.Id,out old)&&old!=FlowSizing.Size(node))sizeMotion[node.Id]=new SizeMotion{From=old,To=FlowSizing.Size(node),At=manipulationClock.ElapsedMilliseconds};}EnsureScene();AnimatePlacement(before);RaiseViewChanged();RequestFrameRepaint();}
 }
